<script>
// @ is an alias to /src
import { Chart } from "chart.js";
import DashboardPopup from "@/components/dashboard/popus/dashboardPopup.vue";
import FilterPopup from "@/components/FilterPopup.vue";
import VisitingTimesChart from "@/components/orderVisitingTimesChart.vue";
import SalesByPaymentMethodChart from "@/components/orderSalesByPaymentMethodChart.vue";
import DashboardBox from "@/components/dashboard/DashboardBox.vue";
import axios from "axios";

export default {
  name: "dashboardHome",
  components: {
    DashboardPopup,
    FilterPopup,
    VisitingTimesChart,
    SalesByPaymentMethodChart,
    DashboardBox,
  },

  data() {
    return {
      filter: "",
      rows: [
        // More products here
      ],
      isPopupVisible: false,
      popupType: "",
      selectedRow: {},
      isLoading: false,
      salesChart: null,
      ordersChart: null,
      resizeTimeout: null,
      chartsInitialized: false,
      userAcquisitionData: {
        days: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
        acquisitions: [10, 15, 8, 12, 20, 18, 14],
        losses: [2, 3, 1, 4, 2, 5, 3],
      },

      search: "",
      currentPage: 1,
      pageSize: 5,
      orders: [
        { orderNumber: 202542, restaurantName: "مطعم الشرق", clientName: "أحمد مصطفى", date: "6 يوليو 2025", price: 150, paymentMethod: "كاش", status: "مكتمل" },
        { orderNumber: 202543, restaurantName: "سانتزو", clientName: "مريم عادل", date: "6 يوليو 2025", price: 150, paymentMethod: "فيزا", status: "ملغي" },
        { orderNumber: 202544, restaurantName: "بيت الكباب", clientName: "يوسف عماد", date: "6 يوليو 2025", price: 150, paymentMethod: "فيزا", status: "جاري التجهيز" },
        { orderNumber: 202545, restaurantName: "ركن الحلويات", clientName: "سارة محمد", date: "6 يوليو 2025", price: 150, paymentMethod: "كاش", status: "قيد التوصيل" },
        { orderNumber: 202546, restaurantName: "سانتزو", clientName: "عمر خالد", date: "6 يوليو 2025", price: 150, paymentMethod: "كاش", status: "مكتمل" },
        // More sample orders...
      ],
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.restName === "string" &&
            row.restName.toLowerCase().includes(searchTerm)) ||
          (row.id && row.id.toString().toLowerCase().includes(searchTerm))
        );
      });
    },
    filteredRestaurants() {
      if (!this.search) return this.restaurants;
      const s = this.search.toLowerCase();
      return this.restaurants.filter(r =>
        r.name.toLowerCase().includes(s) ||
        r.topCategory.toLowerCase().includes(s)
      );
    },
    filteredOrders() {
      if (!this.search) return this.orders;
      const s = this.search.toLowerCase();
      return this.orders.filter(order =>
        order.restaurantName.toLowerCase().includes(s) ||
        order.clientName.toLowerCase().includes(s) ||
        order.status.toLowerCase().includes(s) ||
        order.paymentMethod.toLowerCase().includes(s) ||
        order.orderNumber.toString().includes(s)
      );
    },
    totalPages() {
      return Math.ceil(this.filteredOrders.length / this.pageSize);
    },
    paginatedOrders() {
      const start = (this.currentPage - 1) * this.pageSize;
      return this.filteredOrders.slice(start, start + this.pageSize);
    },
  },
  async mounted() {
    this.isLoading = true;
    this.fetchUserData(); // Fetch user data dynamically
    this.FetchRows(); // Fetch rows dynamically

    // Wait for DOM to be ready and ensure canvas elements exist
    await this.$nextTick();
    
    // Test Chart.js availability
    if (typeof Chart === 'undefined') {
      console.error('Chart.js is not available. Please check the import.');
      return;
    }
    
    console.log('Chart.js is available:', Chart);
    
    // Add a small delay to ensure DOM is fully rendered
    setTimeout(() => {
      this.initializeCharts();
    }, 100);
    
    // Retry chart initialization if it fails
    setTimeout(() => {
      if (!this.chartsInitialized) {
        console.log('Retrying chart initialization...');
        this.initializeCharts();
      }
    }, 500);
    
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
    
    // Add resize listener for responsive charts
    window.addEventListener('resize', this.handleResize);
  },
  beforeUnmount() {
    // Clean up charts to prevent memory leaks
    this.destroyCharts();
    
    // Remove resize listener
    window.removeEventListener('resize', this.handleResize);
  },
  methods: {
    destroyCharts() {
      try {
        if (this.salesChart) {
          this.salesChart.destroy();
          this.salesChart = null;
        }
        if (this.ordersChart) {
          this.ordersChart.destroy();
          this.ordersChart = null;
        }
        this.chartsInitialized = false;
      } catch (error) {
        console.error("Error destroying charts:", error);
      }
    },
    initializeCharts() {
      try {
        if (this.chartsInitialized) {
          return;
        }
        
        // Check if Chart is properly imported
        if (typeof Chart === 'undefined') {
          console.error('Chart is not defined. Chart.js may not be properly imported.');
          return;
        }
        
        console.log('Initializing charts...');
        this.renderSalesPurchasesChart();
        this.renderOrdersChart();
        this.chartsInitialized = true;
        console.log('Charts initialized successfully');
      } catch (error) {
        console.error("Error initializing charts:", error);
      }
    },
    handleResize() {
      // Debounce resize events for better performance
      clearTimeout(this.resizeTimeout);
      this.resizeTimeout = setTimeout(() => {
        try {
          if (this.salesChart && this.salesChart.canvas) {
            this.salesChart.resize();
          }
          if (this.ordersChart && this.ordersChart.canvas) {
            this.ordersChart.resize();
          }
        } catch (error) {
          console.error("Error resizing charts:", error);
        }
      }, 250);
    },
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    FetchRows() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/restaurants",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`, // Add the Authorization header
            },
          }
        )
        .then((response) => {
          this.isLoading = false;
          console.log("Restaurant Response:", response.data); // Log the response
          const data = response.data;
          
          // Check if data exists and has the expected structure
          if (data && data.status && data.data && Array.isArray(data.data)) {
            this.rows = data.data
              .filter((item) => item && item.id) // Filter out items without id
              .map((item) => ({
                id: item.id || `restaurant_${Date.now()}_${Math.random()}`,
                restName: item.name || "N/A",
                email: item.email || "",
                phone: item.phone || "",
                productCount: item.total_products || 0,
                orderCount: item.total_orders || 0,
                lastPurchase: item.last_order || "No orders yet",
              }));
            console.log("Processed rows:", this.rows);
