<template>
  <div class="satisfaction-chart-container">
    <div class="satisfaction-header">
      <div class="satisfaction-title">{{ $t('orderDistributionByStatus') }}</div>
    </div>
    <div class="satisfaction-content">
      <div class="satisfaction-chart-graph-wrapper">
        <Doughnut :data="chartJsData" :options="chartOptions" class="satisfaction-chart-graph" />
      </div>
      <ul class="satisfaction-legend">
        <li class="satisfaction-legend-item" v-for="item in legendItems" :key="item.label">
          <span class="satisfaction-legend-color" :style="{ backgroundColor: item.color }"></span>
          {{ item.label }}
        </li>
      </ul>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { Doughnut } from 'vue-chartjs'
import {
  Chart as ChartJS,
  Title,
  Tooltip,
  Legend,
  ArcElement
} from 'chart.js'

ChartJS.register(Title, Tooltip, Legend, ArcElement)

const { t } = useI18n()

// Data and labels to match the image
const orderStatusLabels = [
  t('inPreparation'), // dark maroon
  t('inProcessing'),  // black
  t('cancelled'),        // light gray
  t('completed')        // gray
]
const orderStatusValues = [47, 40, 23, 20] // as in the image (percentages)
const orderStatusColors = ['#5B183D', '#000000', '#E5E5E5', '#BDBDBD']

const legendItems = computed(() => [
  { label: t('inPreparation'), color: '#5B183D' },
  { label: t('inProcessing'), color: '#000000' },
  { label: t('cancelled'), color: '#E5E5E5' },
  { label: t('completed'), color: '#BDBDBD' },
])

const chartJsData = computed(() => ({
  labels: orderStatusLabels,
  datasets: [
    {
      data: orderStatusValues,
      backgroundColor: orderStatusColors,
      borderWidth: 4
    }
  ]
}))

const chartOptions = {
  cutout: '70%',
  plugins: {
    legend: { display: false },
    tooltip: { enabled: false },
    datalabels: { display: false },
  },
}
</script>

<style scoped>
