  width: 100%;
  box-sizing: border-box;
  
  @media (max-width: 768px) {
    padding: 1.2rem;
  }
  
  @media (max-width: 480px) {
    padding: 1rem;
  }
}
.satisfaction-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}
.satisfaction-filters {
  display: flex;
  flex-direction: row-reverse;
  gap: 0.5rem;
}
.satisfaction-filter-btn {
  background: #f5f5f5;
  border: none;
  border-radius: 1rem;
  padding: 0.3rem 1.2rem;
  font-size: 0.95rem;
  color: #5B183D;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
.satisfaction-filter-btn.active {
  background: #5B183D;
  color: #fff;
}
.satisfaction-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: #222;
  text-align: start;
}
.satisfaction-content {
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}
.satisfaction-chart-graph-wrapper {
  width: 180px;
  min-width: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  
  @media (max-width: 768px) {
    width: 140px;
    min-width: 100px;
  }
  
  @media (max-width: 480px) {
    width: 120px;
    min-width: 80px;
  }
}
.satisfaction-chart-graph {
  width: 9rem !important;
  height: 9rem !important;
}
.satisfaction-legend {
  list-style: none;
  padding: 0;
